(function(root){
 const day=86400000;
 function dates(start,end){const a=Date.parse(start+'T00:00:00Z'),b=Date.parse(end+'T00:00:00Z');if(!Number.isFinite(a)||!Number.isFinite(b)||b<a||b-a>day*365)return [];return Array.from({length:Math.round((b-a)/day)+1},(_,i)=>new Date(a+i*day).toISOString().slice(0,10));}
 function quote(items,selected,tax={}){const ds=[...new Set(selected)].sort(),valid=ds.every(x=>/^\d{4}-\d{2}-\d{2}$/.test(x)&&Number.isFinite(Date.parse(x+'T00:00:00Z'))&&new Date(x+'T00:00:00Z').toISOString().slice(0,10)===x),consecutive=valid&&ds.every((x,i)=>!i||Date.parse(x)-Date.parse(ds[i-1])===day),days=valid?ds.length:0,freeDays=consecutive&&days>=3?1:0;
 const rows=items.map(i=>{const local=i.dates?quote([{p:i.p,q:i.q}],i.dates,{}):null;if(local)return {...local.rows[0],id:i.p.id};const pricing=productPrice(i.p),daily=pricing.base*i.q,saleDaily=pricing.price*i.q,productDiscount=(daily-saleDaily)*days,durationDiscount=saleDaily*freeDays;return {id:i.p.id,name:i.p.name,quantity:i.q,price:pricing.base,effectivePrice:pricing.price,discountPercent:pricing.percent,productDiscount,durationDiscount,dates:ds,days,consecutive,freeDays,paidDays:days-freeDays,gross:daily*days,discount:productDiscount+durationDiscount,total:saleDaily*(days-freeDays)}}),gross=rows.reduce((s,r)=>s+r.gross,0),discount=rows.reduce((s,r)=>s+r.discount,0),subtotal=gross-discount,amount=tax.enabled===true?Math.round(subtotal*Math.max(0,Number(tax.rate)||0)/100):0;const productDiscount=rows.reduce((s,r)=>s+r.productDiscount,0),durationDiscount=rows.reduce((s,r)=>s+r.durationDiscount,0);const allDates=[...new Set(rows.flatMap(r=>r.dates))].sort(),mixed=rows.some(r=>JSON.stringify(r.dates)!==JSON.stringify(rows[0]?.dates));return {dates:allDates,days:allDates.length,consecutive:rows.every(r=>r.consecutive),freeDays:Math.max(0,...rows.map(r=>r.freeDays)),paidDays:mixed?null:rows[0]?.paidDays||0,mixed,rows,gross,discount,productDiscount,durationDiscount,subtotal,tax:amount,total:subtotal+amount};}

 function productPrice(p,now=Date.now()){const active=(!p.discountStart||now>=new Date(p.discountStart+'T00:00:00').getTime())&&(!p.discountEnd||now<=new Date(p.discountEnd+'T23:59:59').getTime()),stopped=['DISCONTINUED','DISCONTINUE'].includes(String(p.labelText||p.label||'').toUpperCase())||p.discontinued===true,percent=active&&!stopped?Math.max(0,Math.min(100,Number(p.discountPercent??p.discount)||0)):0,base=Math.max(0,Number(p.price)||0);return {base,percent,price:Math.round(base*(1-percent/100))};}
 const api={dates,quote,productPrice};root.RentcamRentalPricing=api;if(typeof module==='object')module.exports=api;
})(typeof window==='object'?window:globalThis);
